<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/center_api/products/edit"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('name_en', 'consequatur');
body.append('text_en', 'consequatur');
body.append('name_ar', 'consequatur');
body.append('text_ar', 'consequatur');
body.append('barcode', 'mqeopfuudtdsufvyvddqa');
body.append('measure_unit', 'mniihfqcoynlazghdtqtq');
body.append('measure_amount', '80');
body.append('short_description', 'bajwbpilpmufinllwloau');
body.append('supply_price', '87');
body.append('retail_price', '13');
body.append('markup', '12');
body.append('allow_retail_sales', '');
body.append('track_stock', '1');
body.append('current_stock', '64');
body.append('skus[][sku]', 'msjuryvojcybzvrbyickz');
body.append('skus[][order]', '48');
body.append('image', document.querySelector('input[name="image"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

