    &lt;script&gt;
        $(document).ready(function() {
            $(&quot;#frmLogin&quot;).on(&quot;submit&quot;, function(event) {
                event.preventDefault();

                $.ajax({
                    url: &quot;http://localhost:8000/admin/login&quot;,
                    type: &quot;POST&quot;,
                    data: new FormData(this),
                    contentType: false,
                    processData: false,
                    headers: {
                        &#039;X-CSRF-TOKEN&#039;: $(&#039;meta[name=&quot;csrf-token&quot;]&#039;).attr(&#039;content&#039;) || $(&#039;input[name=&quot;_token&quot;]&#039;).val(),
                        &#039;X-Requested-With&#039;: &#039;XMLHttpRequest&#039;
                    },
                    beforeSend: function() {
                        $(&#039;#listError&#039;).empty();
                        $(&quot;#alertError&quot;).hide();
                        $(&quot;.submitFrom span&quot;).html(&#039;Login In Progress&#039;);
                        $(&#039;.submitFrom&#039;).prop(&#039;disabled&#039;, true);
                    },
                    success: function(response, textStatus, xhr) {
                        if (xhr.status == 200) {
                            window.location.href = &quot;http://localhost:8000/admin/cp&quot;;
                        } else {
                            $(&quot;#alertError&quot;).show();
                            $(&#039;#listError&#039;).html(data.message);
                        }

                        $(&quot;html, body&quot;).animate({
                            scrollTop: 0
                        }, {
                            duration: 1500,
                        });
                        $(&quot;.submitFrom span&quot;).html(&#039;Login&#039;);
                        $(&#039;.submitFrom&#039;).prop(&#039;disabled&#039;, false);
                    },
                    error: function(response) {
                        $(&quot;#alertError&quot;).show();
                        var errors = response.responseJSON.errors;
                        if (errors) {
                            for (var error in errors) {
                                var ul = document.getElementById(&quot;listError&quot;);
                                var li = document.createElement(&quot;li&quot;);
                                li.appendChild(document.createTextNode(errors[error]));
                                ul.appendChild(li);
                            }
                        } else {
