    &lt;script&gt;
        $(document).ready(function() {
            const domainParam = null;
            const postUrl = &quot;http://localhost:8000/center_user/login&quot; + (domainParam ? (&quot;?domain=&quot; + encodeURIComponent(domainParam)) : &quot;&quot;);
            $(&quot;#debug-post-url&quot;).text(postUrl);
            $(&quot;#debug-domain&quot;).text(domainParam || &#039;(none)&#039;);
            $(&quot;#debug-host&quot;).text(window.location.host);

            $(&quot;#frmLogin&quot;).on(&quot;submit&quot;, function(event) {
                event.preventDefault();

                $.ajax({
                    url: postUrl,
                    type: &quot;POST&quot;,
                    data: new FormData(this),
                    contentType: false,
                    processData: false,
                    headers: domainParam ? { &#039;domain&#039;: domainParam } : {},
                    beforeSend: function() {
                        $(&#039;#listError&#039;).empty();
                        $(&quot;#alertError&quot;).hide();
                        $(&quot;.submitFrom span&quot;).html(&#039;Login In Progress&#039;);
                        $(&#039;.submitFrom&#039;).prop(&#039;disabled&#039;, true);
                    },
                    success: function(response, textStatus, xhr) {
                        console.log(&#039;Login response:&#039;, response);
                        $(&#039;#debug-response&#039;).text(JSON.stringify(response));
                        
                        if (xhr.status == 200) {
                            // Check if response contains redirect_url (for root domain login)
                            if (response.data &amp;&amp; response.data.redirect_url) {
                                console.log(&#039;Redirecting to:&#039;, response.data.redirect_url);
                                window.location.href = response.data.redirect_url;
                            } else {
                                // For subdomain login, redirect to cp page
                                console.log(&#039;No redirect_url found, using default redirect&#039;);
                                window.location.href = &quot;http://localhost:8000/center_user/cp&quot; + (domainParam ? (&quot;?domain=&quot; + encodeURIComponent(domainParam)) : &quot;&quot;);
                            }
                        } else {
                            $(&quot;#alertError&quot;).show();
                            $(&#039;#listError&#039;).html(response.message || &#039;Unexpected response&#039;);
                        }

                        $(&quot;html, body&quot;).animate({
                            scrollTop: 0
                        }, {
                            duration: 1500,
                        });
                        $(&quot;.submitFrom span&quot;).html(&#039;Login&#039;);
                        $(&#039;.submitFrom&#039;).prop(&#039;disabled&#039;, false);
                    },
                    error: function(response) {
                        $(&quot;#alertError&quot;).show();
                        var errors = response.responseJSON &amp;&amp; response.responseJSON.errors;
                        if (errors) {
                            for (var error in errors) {
                                var ul = document.getElementById(&quot;listError&quot;);
                                var li = document.createElement(&quot;li&quot;);
                                li.appendChild(document.createTextNode(errors[error]));
                                ul.appendChild(li);
                            }
                        } else if (response.responseJSON &amp;&amp; response.responseJSON.message) {
                            $(&#039;#listError&#039;).html(response.responseJSON.message);
                        } else {
                            $(&#039;#listError&#039;).html(&#039;Login failed with status &#039; + response.status);
                        }

                        $(&quot;html, body&quot;).animate({
                            scrollTop: 0
                        }, {
                            duration: 1500,
                        });
                        $(&quot;.submitFrom span&quot;).html(&#039;Login&#039;);
                        $(&#039;.submitFrom&#039;).prop(&#039;disabled&#039;, false);
                    }
                });
            });
        });
    &lt;/script&gt;
&lt;!-- END: Page JS--&gt;

&lt;script type=&quot;module&quot; src=&quot;https://cdn.datatables.net/buttons/2.3.4/js/buttons.colVis.min.js&quot;&gt;&lt;/script&gt;
