<div class="javascript-example">
    <pre><code class="language-javascript">const url = new URL(
    "http://localhost:8000/center_user/expenses/updateOrCreate"
);

const headers = {
    "Content-Type": "multipart/form-data",
    "Accept": "application/json",
};

const body = new FormData();
body.append('branch_id', 'consequatur');
body.append('amount', '45');
body.append('date', '2026-02-12T11:14:56');
body.append('notes', 'qeopfuudtdsufvyvddqam');
body.append('receipt_image', document.querySelector('input[name="receipt_image"]').files[0]);

fetch(url, {
    method: "POST",
    headers,
    body,
}).then(response =&gt; response.json());</code></pre></div>

