        &lt;style&gt;
            body {
            font-family: &#039;Inter&#039;, sans-serif;
            background-color: #212529;
            color: white;
        }
        
        /* Custom scrollbar */
        ::-webkit-scrollbar {
            width: 8px;
        }
        
        ::-webkit-scrollbar-track {
            background: #212529;
        }
        
        ::-webkit-scrollbar-thumb {
            background: #ffc107;
            border-radius: 4px;
        }
        
        ::-webkit-scrollbar-thumb:hover {
            background: #e0a800;
        }
        
        .hero-section {
            min-height: 100vh;
            position: relative;
            overflow: hidden;
        }

        .hero-section::before {
            content: &#039;&#039;;
            position: absolute;
            top: 0;
            right: 0;
            bottom: 0;
            left: 0;
            background-image: url(&#039;http://localhost:8000/assets/img/background.png&#039;);
            background-size: cover;
            background-position: center;
            background-repeat: no-repeat;
            filter: blur(6px);
            transform: scale(1.05); /* avoid edge transparency after blur */
            z-index: 0;
        }

        .hero-section .container {
            position: relative;
            width: 90%;
            z-index: 1;
        }
        
        .btn-custom {
            background-color: #ffc107;
            border-color: #ffc107;
            color: #212529;
            font-weight: 500;
            padding: 6px 20px;
            border-radius: 6px;
            font-size: 0.8rem;
            transition: all 0.3s ease;
        }
        
        .btn-custom:hover {
            background-color: #e0a800;
            border-color: #e0a800;
            color: #212529;
            transform: translateY(-2px);
            box-shadow: 0 4px 12px rgba(255, 193, 7, 0.3);
        }
        
        .btn-outline-custom {
            border: 2px solid #ffc107;
            color: #ffc107;
            background-color: transparent;
            font-weight: 500;
            padding: 4px 20px;
            border-radius: 6px;
            font-size: 0.8rem;
            transition: all 0.3s ease;
        }
        
        .btn-outline-custom:hover {
            background-color: #ffc107;
            border-color: #ffc107;
            color: #212529;
            transform: translateY(-2px);
        }
        
        /* Mobile spacing adjustments */
        @media (max-width: 768px) {
            .hero-section {
                min-height: 60vh;
                padding-bottom: 2rem;
            }
            
            #about {
                margin-top: -1rem;
            }
            }
