                    &lt;div class=&quot;pagination-dots d-flex justify-content-center align-items-center gap-2&quot;&gt;
                                                
                                                    &lt;button class=&quot;pagination-dot &quot; onclick=&quot;goToTestimonial(0)&quot; style=&quot;width: 12px; height: 12px; border-radius: 50%; border: none; background-color: #6c757d; transition: all 0.3s ease;&quot; onmouseover=&quot;this.style.transform=&#039;scale(1.2)&#039;&quot; onmouseout=&quot;this.style.transform=&#039;scale(1)&#039;&quot;&gt;&lt;/button&gt;
