&lt;script&gt;
let currentTestimonial = 1; // Start with second testimonial (index 1)
const testimonials = [&quot;Luzori transformed our business with their exceptional web design and development services. Their attention to detail and innovative solutions exceeded our expectations. Highly recommended!&quot;,&quot;Working with Luzori was a game-changer for our startup. They delivered a stunning website that perfectly captured our brand vision and helped us attract more customers.&quot;,&quot;The team at Luzori is incredibly professional and talented. They took our complex requirements and turned them into a beautiful, functional digital solution that our users love.&quot;,&quot;Luzori\u0027s mobile app development expertise helped us reach our customers on all platforms. The app they built is fast, intuitive, and exactly what we needed.&quot;,&quot;From concept to launch, Luzori guided us through every step of our digital transformation. Their strategic approach and technical excellence made all the difference.&quot;];

function changeTestimonial(direction) {
    const testimonialText = document.getElementById(&#039;testimonial-text&#039;);
    const dots = document.querySelectorAll(&#039;.pagination-dot&#039;);
    
    // Add fade out animation
    testimonialText.style.opacity = &#039;0&#039;;
    testimonialText.style.transform = &#039;translateY(20px)&#039;;
    
    setTimeout(() =&gt; {
        // Update testimonial
        currentTestimonial += direction;
        
        // Loop around
        if (currentTestimonial &lt; 0) {
            currentTestimonial = testimonials.length - 1;
        } else if (currentTestimonial &gt;= testimonials.length) {
            currentTestimonial = 0;
        }
        
        // Update content
        testimonialText.textContent = testimonials[currentTestimonial];
        
        // Update dots
        dots.forEach((dot, index) =&gt; {
            dot.classList.remove(&#039;active&#039;);
            dot.style.backgroundColor = index === currentTestimonial ? &#039;#ffc107&#039; : &#039;#6c757d&#039;;
        });
        
        // Add fade in animation
        testimonialText.style.opacity = &#039;1&#039;;
        testimonialText.style.transform = &#039;translateY(0)&#039;;
    }, 250);
}

function goToTestimonial(index) {
    const testimonialText = document.getElementById(&#039;testimonial-text&#039;);
    const dots = document.querySelectorAll(&#039;.pagination-dot&#039;);
    
    if (index === currentTestimonial) return;
    
    // Add fade out animation
    testimonialText.style.opacity = &#039;0&#039;;
    testimonialText.style.transform = &#039;translateY(20px)&#039;;
    
    setTimeout(() =&gt; {
        // Update testimonial
        currentTestimonial = index;
        
        // Update content
        testimonialText.textContent = testimonials[currentTestimonial];
        
        // Update dots
        dots.forEach((dot, dotIndex) =&gt; {
            dot.classList.remove(&#039;active&#039;);
            dot.style.backgroundColor = dotIndex === currentTestimonial ? &#039;#ffc107&#039; : &#039;#6c757d&#039;;
        });
        
        // Add fade in animation
        testimonialText.style.opacity = &#039;1&#039;;
        testimonialText.style.transform = &#039;translateY(0)&#039;;
    }, 250);
}

// Auto-rotate testimonials every 5 seconds
setInterval(() =&gt; {
    changeTestimonial(1);
}, 5000);

// Initialize
document.addEventListener(&#039;DOMContentLoaded&#039;, function() {
    const testimonialText = document.getElementById(&#039;testimonial-text&#039;);
    testimonialText.style.transition = &#039;all 0.5s ease&#039;;
});
&lt;/script&gt;

