    animation: slideInLeft 1.2s ease-out 0.3s both;
}

.testimonial-card .position-absolute:last-child {
    animation: slideInRight 1.2s ease-out 0.3s both;
}

/* Text animation */
.testimonial-text {
    animation: fadeInUp 1s ease-out 0.5s both;
}

/* Navigation arrows */
.testimonial-nav {
    opacity: 0.7;
}

.testimonial-nav:hover {
    opacity: 1;
    color: #e0a800 !important;
}

/* Pagination dots */
.pagination-dot {
    cursor: pointer;
}

.pagination-dot:hover {
    background-color: #ffc107 !important;
}

.pagination-dot.active {
    transform: scale(1.2);
}

/* Responsive design */
@media (max-width: 768px) {
    .testimonial-card {
        padding: 2rem !important;
        margin: 0 1rem;
    }
    
    .testimonial-nav {
        display: none;
    }
    
    .testimonial-card .position-absolute:first-child,
    .testimonial-card .position-absolute:last-child {
        font-size: 3rem !important;
    }
}

/* Smooth transitions */
.testimonial-text {
    transition: all 0.5s ease;
}

.pagination-dot {
    transition: all 0.3s ease;
}

/* Card entrance animation */
.testimonial-card {
    animation: fadeInUp 0.8s ease-out;
}

/* Quote mark animations */
@keyframes quoteAppear {
    from {
        opacity: 0;
        transform: scale(0);
    }
    to {
        opacity: 1;
        transform: scale(1);
    }
}

.testimonial-card .position-absolute:first-child,
.testimonial-card .position-absolute:last-child {
    animation: quoteAppear 0.6s ease-out 0.8s both;
}
&lt;/style&gt;
        
