&lt;script&gt;
function filterFAQ(category) {
    // Remove active class from all tabs
    document.querySelectorAll(&#039;.btn-group .btn&#039;).forEach(btn =&gt; {
        btn.classList.remove(&#039;active&#039;, &#039;btn-warning&#039;);
        btn.classList.add(&#039;btn-outline-warning&#039;);
    });
    
    // Add active class to clicked tab
    const activeTab = document.getElementById(category + &#039;-tab&#039;);
    activeTab.classList.add(&#039;active&#039;, &#039;btn-warning&#039;);
    activeTab.classList.remove(&#039;btn-outline-warning&#039;);
    
    // Hide all FAQ categories
    document.querySelectorAll(&#039;.faq-category&#039;).forEach(cat =&gt; {
        cat.style.display = &#039;none&#039;;
    });
    
    // Show selected category
    document.getElementById(&#039;faq-&#039; + category).style.display = &#039;block&#039;;
    
    // Reset all FAQ items in the new category
    const categoryFAQs = document.querySelectorAll(&#039;#faq-&#039; + category + &#039; .faq-item&#039;);
    categoryFAQs.forEach((item, index) =&gt; {
        const collapse = item.querySelector(&#039;.collapse&#039;);
        const icon = item.querySelector(&#039;.faq-icon&#039;);
        const plusIcon = item.querySelector(&#039;.plus-icon&#039;);
        const minusIcon = item.querySelector(&#039;.minus-icon&#039;);
        
        // Close all items
        collapse.classList.remove(&#039;show&#039;);
        plusIcon.style.display = &#039;inline&#039;;
        minusIcon.style.display = &#039;none&#039;;
        
        // Add entrance animation
        item.style.animation = &#039;fadeInUp 0.6s ease-out &#039; + (index * 0.1) + &#039;s both&#039;;
    });
}

function toggleFAQ(button) {
    const collapse = button.nextElementSibling;
    const icon = button.querySelector(&#039;.faq-icon&#039;);
    const plusIcon = button.querySelector(&#039;.plus-icon&#039;);
    const minusIcon = button.querySelector(&#039;.minus-icon&#039;);
    
    // Toggle collapse
    if (collapse.classList.contains(&#039;show&#039;)) {
        collapse.classList.remove(&#039;show&#039;);
        plusIcon.style.display = &#039;inline&#039;;
        minusIcon.style.display = &#039;none&#039;;
        icon.style.transform = &#039;rotate(0deg)&#039;;
    } else {
        collapse.classList.add(&#039;show&#039;);
        plusIcon.style.display = &#039;none&#039;;
        minusIcon.style.display = &#039;inline&#039;;
        icon.style.transform = &#039;rotate(180deg)&#039;;
    }
}

// Initialize with general category
document.addEventListener(&#039;DOMContentLoaded&#039;, function() {
    filterFAQ(&#039;general&#039;);
});
&lt;/script&gt;

&lt;style&gt;
/* FAQ Animations */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes slideInLeft {
    from {
        opacity: 0;
        transform: translateX(-50px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/* Section animations */
.faq-container {
    animation: fadeInUp 0.8s ease-out;
}

.faq-item {
    animation: fadeInUp 0.6s ease-out both;
}

/* Tab Button Styles */
.btn-group .btn {
    transition: all 0.3s ease;
}

.btn-group .btn:hover {
    transform: translateY(-2px);
}

/* FAQ Card Styles */
.faq-item .card {
    border: 1px solid rgba(255, 193, 7, 0.1);
    transition: all 0.3s ease;
}

.faq-item .card:hover {
    border-color: rgba(255, 193, 7, 0.3);
    box-shadow: 0 5px 15px rgba(0, 0, 0, 0.2);
}

/* FAQ Toggle Button */
.faq-toggle {
    transition: all 0.3s ease;
}

.faq-toggle:hover {
    background-color: rgba(255, 193, 7, 0.1);
}

/* Icon Animation */
.faq-icon {
    transition: transform 0.3s ease;
}

.faq-icon:hover {
    transform: scale(1.2);
}

/* Collapse Animation */
.collapse {
    transition: all 0.3s ease;
}

.collapse.show {
    animation: slideInLeft 0.3s ease-out;
}

/* Responsive Design */
@media (max-width: 768px) {
    .btn-group {
        flex-direction: column;
        width: 100%;
    }
    
    .btn-group .btn {
        margin-bottom: 0.5rem;
        margin-right: 0 !important;
    }
    
    .faq-toggle {
        padding: 1rem !important;
    }
    
    .faq-toggle h6 {
        font-size: 0.9rem;
    }
}

/* Smooth transitions */
.faq-category {
    transition: all 0.3s ease;
}

.faq-item .card-body {
    transition: all 0.3s ease;
}

/* Hover effects */
.faq-item:hover .card {
    transform: translateY(-2px);
    box-shadow: 0 8px 25px rgba(0, 0, 0, 0.3);
}

/* Active state styling */
.btn-warning {
    background-color: #ffc107 !important;
    border-color: #ffc107 !important;
    color: #212529 !important;
}

.btn-outline-warning:hover {
    background-color: #ffc107;
    border-color: #ffc107;
    color: #212529;
}
&lt;/style&gt;
        
        
