&lt;script&gt;
// Form validation and submission
document.addEventListener(&#039;DOMContentLoaded&#039;, function() {
    const form = document.getElementById(&#039;contactForm&#039;);
    const submitBtn = form.querySelector(&#039;button[type=&quot;submit&quot;]&#039;);
    
    form.addEventListener(&#039;submit&#039;, function(event) {
        event.preventDefault();
        event.stopPropagation();
        
        if (form.checkValidity()) {
            // Show loading state
            const originalText = submitBtn.innerHTML;
            submitBtn.innerHTML = &#039;&lt;span class=&quot;spinner-border spinner-border-sm me-2&quot; role=&quot;status&quot; aria-hidden=&quot;true&quot;&gt;&lt;/span&gt;Sending...&#039;;
            submitBtn.disabled = true;
            
            // Prepare form data
            const formData = new FormData(form);
            
            // Send AJAX request
            fetch(form.action, {
                method: &#039;POST&#039;,
                body: formData,
                headers: {
                    &#039;X-Requested-With&#039;: &#039;XMLHttpRequest&#039;,
                    &#039;X-CSRF-TOKEN&#039;: document.querySelector(&#039;meta[name=&quot;csrf-token&quot;]&#039;)?.getAttribute(&#039;content&#039;) || formData.get(&#039;_token&#039;)
                }
            })
            .then(response =&gt; response.json())
            .then(data =&gt; {
                if (data.success) {
                    showSuccessMessage(data.message);
                    form.reset();
                    form.classList.remove(&#039;was-validated&#039;);
                } else {
                    showErrorMessage(data.message || &#039;An error occurred. Please try again.&#039;);
                }
            })
            .catch(error =&gt; {
                console.error(&#039;Error:&#039;, error);
                showErrorMessage(&#039;Network error. Please check your connection and try again.&#039;);
            })
            .finally(() =&gt; {
                // Reset button state
                submitBtn.innerHTML = originalText;
                submitBtn.disabled = false;
            });
        } else {
            form.classList.add(&#039;was-validated&#039;);
        }
    });
    
    // Real-time validation
    const inputs = form.querySelectorAll(&#039;input, textarea&#039;);
    inputs.forEach(input =&gt; {
        input.addEventListener(&#039;blur&#039;, function() {
            if (this.checkValidity()) {
                this.classList.remove(&#039;is-invalid&#039;);
                this.classList.add(&#039;is-valid&#039;);
            } else {
                this.classList.remove(&#039;is-valid&#039;);
                this.classList.add(&#039;is-invalid&#039;);
            }
        });
    });
});

function showSuccessMessage(message = &#039;Your message has been sent successfully! We\&#039;ll get back to you soon!&#039;) {
    // Create success alert
    const alertDiv = document.createElement(&#039;div&#039;);
    alertDiv.className = &#039;alert alert-success alert-dismissible fade show position-fixed&#039;;
    alertDiv.style.cssText = &#039;top: 20px; right: 20px; z-index: 9999; min-width: 300px;&#039;;
    alertDiv.innerHTML = `
        &lt;strong&gt;Success!&lt;/strong&gt; ${message}
        &lt;button type=&quot;button&quot; class=&quot;btn-close&quot; data-bs-dismiss=&quot;alert&quot;&gt;&lt;/button&gt;
    `;
    
    document.body.appendChild(alertDiv);
    
    // Auto remove after 5 seconds
    setTimeout(() =&gt; {
        if (alertDiv.parentNode) {
            alertDiv.remove();
        }
    }, 5000);
}

function showErrorMessage(message) {
    // Create error alert
    const alertDiv = document.createElement(&#039;div&#039;);
    alertDiv.className = &#039;alert alert-danger alert-dismissible fade show position-fixed&#039;;
    alertDiv.style.cssText = &#039;top: 20px; right: 20px; z-index: 9999; min-width: 300px;&#039;;
    alertDiv.innerHTML = `
        &lt;strong&gt;Error!&lt;/strong&gt; ${message}
        &lt;button type=&quot;button&quot; class=&quot;btn-close&quot; data-bs-dismiss=&quot;alert&quot;&gt;&lt;/button&gt;
    `;
    
    document.body.appendChild(alertDiv);
    
    // Auto remove after 7 seconds
    setTimeout(() =&gt; {
        if (alertDiv.parentNode) {
            alertDiv.remove();
        }
    }, 7000);
}

// Add focus effects to form controls
document.querySelectorAll(&#039;.form-control&#039;).forEach(control =&gt; {
    control.addEventListener(&#039;focus&#039;, function() {
        this.style.borderColor = &#039;#ffc107&#039;;
        this.style.boxShadow = &#039;0 0 0 0.2rem rgba(255, 193, 7, 0.25)&#039;;
    });
    
    control.addEventListener(&#039;blur&#039;, function() {
        this.style.borderColor = &#039;#6c757d&#039;;
        this.style.boxShadow = &#039;none&#039;;
    });
});
&lt;/script&gt;

&lt;script&gt;
// Update country flag when country code changes
document.addEventListener(&#039;DOMContentLoaded&#039;, function(){
    const select = document.getElementById(&#039;country_code&#039;);
    const flagImg = document.getElementById(&#039;countryFlag&#039;);
    const map = {
        &#039;+971&#039;: &#039;ae&#039;, &#039;+966&#039;: &#039;sa&#039;, &#039;+974&#039;: &#039;qa&#039;, &#039;+968&#039;: &#039;om&#039;, &#039;+965&#039;: &#039;kw&#039;, &#039;+973&#039;: &#039;bh&#039;,
        &#039;+20&#039;: &#039;eg&#039;, &#039;+963&#039;: &#039;sy&#039;, &#039;+962&#039;: &#039;jo&#039;, &#039;+970&#039;: &#039;ps&#039;, &#039;+961&#039;: &#039;lb&#039;, &#039;+90&#039;: &#039;tr&#039;,
        &#039;+212&#039;: &#039;ma&#039;, &#039;+216&#039;: &#039;tn&#039;, &#039;+213&#039;: &#039;dz&#039;, &#039;+44&#039;: &#039;gb&#039;, &#039;+1&#039;: &#039;us&#039;, &#039;+49&#039;: &#039;de&#039;,
        &#039;+33&#039;: &#039;fr&#039;, &#039;+91&#039;: &#039;in&#039;, &#039;+92&#039;: &#039;pk&#039;
    };
    function updateFlag(){
        const code = select ? select.value : &#039;+971&#039;;
        const cc = map[code] || &#039;ae&#039;;
        if(flagImg){ flagImg.src = `https://flagcdn.com/w20/${cc}.png`; }
    }
    if(select){
        select.addEventListener(&#039;change&#039;, updateFlag);
        updateFlag();
    }
});
&lt;/script&gt;

&lt;style&gt;
/* Contact Section Animations */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes slideInLeft {
    from {
        opacity: 0;
        transform: translateX(-50px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

@keyframes slideInRight {
    from {
        opacity: 0;
        transform: translateX(50px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/* Section animations */
.contact-info-card {
    animation: slideInLeft 0.8s ease-out;
}

.contact-form-card {
    animation: slideInRight 0.8s ease-out;
}

/* Contact info card hover effect */
.contact-info-card:hover {
    transform: translateY(-5px);
    box-shadow: 0 15px 40px rgba(0, 0, 0, 0.4) !important;
    border-color: rgba(255, 193, 7, 0.5) !important;
}

/* Contact items animation */
.contact-item {
    animation: fadeInUp 0.6s ease-out both;
}

.contact-item:nth-child(2) {
    animation-delay: 0.1s;
}

.contact-item:nth-child(3) {
    animation-delay: 0.2s;
}

.contact-item:nth-child(4) {
    animation-delay: 0.3s;
}

/* Contact icon hover effect */
.contact-icon {
    transition: all 0.3s ease;
}

.contact-item:hover .contact-icon {
    transform: scale(1.1);
    background-color: rgba(255, 193, 7, 0.3) !important;
}

/* Form styling */
.form-control {
    transition: all 0.3s ease;
}

.form-control:focus {
    border-color: #ffc107 !important;
    box-shadow: 0 0 0 0.2rem rgba(255, 193, 7, 0.25) !important;
}

.form-control::placeholder {
    color: #adb5bd;
}

/* RTL alignment for Arabic locale */
[dir=&quot;rtl&quot;] input.form-control,
[dir=&quot;rtl&quot;] textarea.form-control {
    direction: rtl;
    text-align: right;
}

/* Keep numbers LTR inside RTL layouts */
.ltr-number {
    direction: ltr !important;
    unicode-bidi: bidi-override;
}

[dir=&quot;rtl&quot;] input.form-control::placeholder,
[dir=&quot;rtl&quot;] textarea.form-control::placeholder {
    direction: rtl;
    text-align: right;
}

/* Button animation */
.btn-warning {
    position: relative;
    overflow: hidden;
}

.btn-warning::before {
    content: &#039;&#039;;
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.2), transparent);
    transition: left 0.5s ease;
}

.btn-warning:hover::before {
    left: 100%;
}

/* Responsive design */
@media (max-width: 768px) {
    .contact-info-card,
    .contact-form-card {
        margin-bottom: 2rem;
    }
    
    .contact-item {
        margin-bottom: 1.5rem;
    }
    
    .btn-lg {
        padding: 0.75rem 2rem;
    }
}

/* Phone input group sizing */
.input-group select[name=&quot;country_code&quot;] {
    flex: 0 0 110px;
}

@media (max-width: 576px) {
    .input-group select[name=&quot;country_code&quot;] {
        flex: 0 0 80px !important;
        font-size: 0.85rem;
        padding: .375rem .5rem;
    }

    .input-group #phone {
        font-size: 0.95rem;
        padding: .375rem .5rem;
    }
}

/* Country flag spacing */
.input-group-text img { display: block; }

/* Success message styling */
.alert-success {
    background-color: rgba(25, 135, 84, 0.9);
    border-color: #198754;
    color: white;
}

/* Form validation styling */
.is-valid {
    border-color: #198754 !important;
}

.is-invalid {
    border-color: #dc3545 !important;
}

/* Smooth transitions */
.contact-info-card,
.contact-form-card,
.contact-item,
.form-control,
.btn-warning {
    transition: all 0.3s ease;
}
&lt;/style&gt;
