&lt;style&gt;
/* Footer Animations */
@keyframes fadeInUp {
    from {
        opacity: 0;
        transform: translateY(30px);
    }
    to {
        opacity: 1;
        transform: translateY(0);
    }
}

@keyframes slideInLeft {
    from {
        opacity: 0;
        transform: translateX(-50px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

@keyframes slideInRight {
    from {
        opacity: 0;
        transform: translateX(50px);
    }
    to {
        opacity: 1;
        transform: translateX(0);
    }
}

/* Section animations */
.footer-brand {
    animation: slideInLeft 0.8s ease-out;
}

.footer-section:nth-child(2) {
    animation: fadeInUp 0.8s ease-out 0.1s both;
}

.footer-section:nth-child(3) {
    animation: fadeInUp 0.8s ease-out 0.2s both;
}

.footer-section:nth-child(4) {
    animation: slideInRight 0.8s ease-out 0.3s both;
}

/* Logo animation */
.footer-brand img {
    transition: all 0.3s ease;
}

.footer-brand:hover img {
    transform: scale(1.05);
    filter: brightness(1.1);
}

/* Footer links animation */
.footer-link {
    position: relative;
    display: inline-block;
}

.footer-link::before {
    content: &#039;&#039;;
    position: absolute;
    bottom: -2px;
    left: 0;
    width: 0;
    height: 2px;
    background-color: #ffc107;
    transition: width 0.3s ease;
}

.footer-link:hover::before {
    width: 100%;
}

/* Social links animation */
.social-item {
    animation: fadeInUp 0.6s ease-out both;
}

.social-item:nth-child(1) { animation-delay: 0.1s; }
.social-item:nth-child(2) { animation-delay: 0.2s; }
.social-item:nth-child(3) { animation-delay: 0.3s; }
.social-item:nth-child(4) { animation-delay: 0.4s; }
.social-item:nth-child(5) { animation-delay: 0.5s; }

.social-link {
    position: relative;
    overflow: hidden;
}

.social-link::before {
    content: &#039;&#039;;
    position: absolute;
    top: 0;
    left: -100%;
    width: 100%;
    height: 100%;
    background: linear-gradient(90deg, transparent, rgba(255, 255, 255, 0.1), transparent);
    transition: left 0.5s ease;
}

.social-link:hover::before {
    left: 100%;
}

/* Responsive design */
@media (max-width: 768px) {
    .footer-section {
        margin-bottom: 2rem;
    }
    
    .social-item {
        margin-bottom: 0.75rem;
    }
    
    .social-link {
        padding: 0.5rem !important;
    }
    
    .social-link svg {
        width: 16px;
        height: 16px;
    }
}

/* Smooth transitions */
.footer-brand,
.footer-section,
.footer-link,
.social-link {
    transition: all 0.3s ease;
}

/* Hover effects */
.footer-section:hover h5 {
    color: #ffc107;
}

/* Copyright animation */
hr {
    animation: fadeInUp 0.8s ease-out 0.6s both;
}

.text-center p {
    animation: fadeInUp 0.8s ease-out 0.7s both;
}
&lt;/style&gt;
