    "email": "kunde.eloisa@example.com",
    "country_code": "hfqco",
    "phone": "ynlazghdtqtqxbajw",
    "subject": "bpilpmufinllwloauydls",
    "message": "msjuryvojcybzvrbyickz"
};

fetch(url, {
    method: "POST",
    headers,
    body: JSON.stringify(body),
}).then(response =&gt; response.json());</code></pre></div>

